import{_ as o,c as a,o as l,ag as t}from"./chunks/framework.B1jFR3yW.js";const s=JSON.parse('{"title":"Python 包管理与环境","description":"","frontmatter":{},"headers":[],"relativePath":"python/包管理与环境/index.md","filePath":"python/包管理与环境/index.md"}'),i={name:"python/包管理与环境/index.md"};function d(c,e,r,h,n,u){return l(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="python-包管理与环境" tabindex="-1">Python 包管理与环境 <a class="header-anchor" href="#python-包管理与环境" aria-label="Permalink to &quot;Python 包管理与环境&quot;">​</a></h1><h2 id="这部分讲什么" tabindex="-1">这部分讲什么 <a class="header-anchor" href="#这部分讲什么" aria-label="Permalink to &quot;这部分讲什么&quot;">​</a></h2><p>写 Python 时，真正影响开发效率的，往往不是语法，而是环境和依赖管理是否清晰。</p><p>这一组文档主要补充 4 个高频工具：</p><ul><li><code>uv</code>：现代化、速度很快，适合新项目</li><li><code>conda</code>：环境隔离和科学计算生态更强，适合数据分析</li><li><code>poetry</code>：偏工程化的依赖管理和打包工具</li><li><code>jupyter</code>：交互式实验、数据探索和教学演示工具</li></ul><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><p>如果你是从零开始，建议按下面顺序看：</p><ol><li><a href="./uv.html">uv 使用指南</a></li><li><a href="./conda.html">conda 使用指南</a></li><li><a href="./poetry.html">poetry 使用指南</a></li><li><a href="./jupyter.html">jupyter 使用指南</a></li></ol><h2 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h2><h3 id="_1-日常脚本和新项目" tabindex="-1">1. 日常脚本和新项目 <a class="header-anchor" href="#_1-日常脚本和新项目" aria-label="Permalink to &quot;1. 日常脚本和新项目&quot;">​</a></h3><p>优先考虑 <code>uv</code>：</p><ul><li>启动快</li><li>装包快</li><li>虚拟环境、依赖、工具运行可以统一管理</li></ul><h3 id="_2-数据分析和科学计算" tabindex="-1">2. 数据分析和科学计算 <a class="header-anchor" href="#_2-数据分析和科学计算" aria-label="Permalink to &quot;2. 数据分析和科学计算&quot;">​</a></h3><p>优先考虑 <code>conda</code>：</p><ul><li>更适合需要 <code>numpy</code>、<code>pandas</code>、<code>jupyter</code>、<code>pytorch</code> 这类生态的场景</li><li>对非 Python 依赖也更友好</li></ul><h3 id="_3-需要打包和发布-python-项目" tabindex="-1">3. 需要打包和发布 Python 项目 <a class="header-anchor" href="#_3-需要打包和发布-python-项目" aria-label="Permalink to &quot;3. 需要打包和发布 Python 项目&quot;">​</a></h3><p>可以考虑 <code>poetry</code>：</p><ul><li><code>pyproject.toml</code> 管理体验完整</li><li>锁版本、运行命令、构建发布都比较顺手</li></ul><h3 id="_4-数据探索和教学演示" tabindex="-1">4. 数据探索和教学演示 <a class="header-anchor" href="#_4-数据探索和教学演示" aria-label="Permalink to &quot;4. 数据探索和教学演示&quot;">​</a></h3><p>使用 <code>jupyter</code>：</p><ul><li>适合边写代码边看结果</li><li>很适合分析 CSV、画图、写实验记录</li></ul><h2 id="一个简单判断" tabindex="-1">一个简单判断 <a class="header-anchor" href="#一个简单判断" aria-label="Permalink to &quot;一个简单判断&quot;">​</a></h2><ul><li>想要更现代、更轻量：用 <code>uv</code></li><li>想做数据分析、机器学习：用 <code>conda</code></li><li>想做可发布的 Python 包：用 <code>poetry</code></li><li>想做交互式分析：用 <code>jupyter</code></li></ul><h2 id="建议" tabindex="-1">建议 <a class="header-anchor" href="#建议" aria-label="Permalink to &quot;建议&quot;">​</a></h2><ul><li>同一项目尽量只选一套主工具链，不要混着管依赖。</li><li>如果已经用了 <code>conda</code> 管环境，就不要再让 <code>poetry</code> 或 <code>uv</code> 额外接管同一个环境里的全部依赖。</li><li><code>jupyter</code> 只是交互界面，本身不负责完整依赖管理，通常要配合 <code>uv</code>、<code>conda</code> 或 <code>poetry</code> 一起使用。</li></ul>',25)])])}const y=o(i,[["render",d]]);export{s as __pageData,y as default};
